using System;using System.Linq;using System.Text.Json;using BusinessAsUsual.Town;using BusinessAsUsual.Phase8B;
class Program {
 static int checks;static void Check(bool value,string why){checks++;if(!value)throw new Exception(why);}
 static void Main(){
  var chosen=new int[3];for(int seed=0;seed<120;seed++){var d=new SuspiciousDayDomain();for(ulong i=10;i<13;i++){d.Register(i,(int)(i-9));d.Ready(i,out _);}Check(d.Start(false,seed,1,10,new ulong[]{10,11,12},out _),"ready start");var selected=new ulong[]{10,11,12}.Where(i=>d.CopyFor(i).hasArrangement).ToArray();Check(selected.Length==1,"exactly one private arrangement");chosen[selected[0]-10]++;Check(!new ulong[]{10,11,12}.Any(i=>d.CopyFor(i).practice),"no practice flag in multiplayer");string json=JsonSerializer.Serialize(d.Public,new JsonSerializerOptions{IncludeFields=true});Check(!json.Contains("arrangement")&&!json.Contains("seed")&&!json.Contains("personal"),"public state excludes private assignment and RNG seed");}
  Check(chosen.All(n=>n>0),"hidden status can belong to every public profession");
  var solo=new SuspiciousDayDomain();solo.Register(1,1,"identity");Check(!solo.Start(true,1,1,1,new ulong[]{1},out _),"unready cannot start");solo.Ready(1,out _);Check(solo.Start(true,1,1,1,new ulong[]{1},out _),"solo ready start");Check(solo.CopyFor(1).practice,"solo is labelled practice");solo.Accepted(1,"hold-return",true);solo.Accepted(1,"note-direct",false);Check(!solo.CopyFor(1).Complete,"detour requires useful work");solo.Accepted(1,"scan-order",false);Check(solo.CopyFor(1).Complete,"productive cover completes arrangement");solo.Disconnect(1);solo.Register(7,1,"identity");Check(solo.CopyFor(7).Complete&&solo.CopyFor(7).practice,"same live identity retains private progress");Check(!solo.CopyFor(99).hasArrangement,"late unknown worker gets no reroll");
  foreach(string route in new[]{"hold-return","hold-yard"}){var w=new WorkdayDomain(true,true);bool Act(string action,int job=1)=>w.Apply(action,job,false,10,1+checks,out _);Check(Act("receive")&&Act("prepare")&&Act("pickup"),"ordinary parcel setup");Check(Act(route),"lawful shared hold");Check(w.Conserved&&w.Find("PART-8A-001").holder==WorkdayDomain.Nobody,"supported same-identity staging");Check(Act("return-note")&&w.State.parcelNote=="Held for stock check","ordinary first declaration");Check(Act("return-note")&&w.State.parcelNote=="Direct transfer","direct declaration is a supported player action");Check(w.Records.Any(r=>r.heading=="Holding slip")&&w.Records.Count(r=>r.heading=="Declared transfer")==2,"scope and amendment traces exist");Check(Act(route)&&Act("deliver"),"retrieval resumes original repair chain");Check(w.Find("PART-8A-001").custody=="garage"&&w.Conserved,"no replacement item minted");Check(!Act("return-note"),"unstaged parcel cannot receive a hold note");Check(w.PublicState().suspicious&&w.PublicState().records.Length==0,"active mode replicated but professional papers separate");}
  var normal=new WorkdayDomain(true);Check(!normal.Apply("hold-return",1,false,1,1,out _),"legacy mode does not acquire new staging actions");
  var correction=new WorkdayDomain(true,true);Check(!correction.Apply("amend-service",2,false,1,1,out _),"no correction before diagnosis");correction.Apply("hood",2,false,1,2,out _);correction.Apply("diagnose",2,false,1,3,out _);Check(correction.Apply("amend-service",2,false,1,4,out _)&&correction.Records.Any(r=>r.heading=="Service amendment"),"ordinary correction preserves a trace");Check(correction.Conserved,"correction changes no inventory");
  var intake=new WorkdayDomain(true,true);foreach(var action in new[]{"receive","prepare","pickup","deliver"})Check(intake.Apply(action,1,false,1,4,out _),"initial sealed delivery");Check(intake.Apply("collect-parcel",2,false,2,5,out _)&&intake.Find("PART-8A-001").holder==2&&intake.Find("PACK-8A-001").holder==2,"mechanic can lawfully lift unopened parcel for a recheck");Check(intake.Apply("hold-yard",2,false,2,6,out _)&&intake.Conserved,"received parcel can take the second ordinary route");
  var helper=new SuspiciousDayDomain();helper.Register(5,1);helper.Ready(5,out _);helper.Start(true,1,1,5,new ulong[]{5},out _);helper.Accepted(5,"assist",false);Check(helper.CopyFor(5).productive,"production gate assistance counts as useful work");
  Console.WriteLine($"PASS {checks} suspicious-day assertions (120 assignment seeds, both ordinary routes, cover, reconnect, declarations, corrections and legacy isolation)");
 }
}
